function gestureBaseline(){const points=[...touchPoints.values()];if(!points.length){touchGesture=null;return}const a=points[0],b=points[1]||a;touchGesture={...cropSnapshot(),cx:(a.x+b.x)/2,cy:(a.y+b.y)/2,angle:Math.atan2(b.y-a.y,b.x-a.x)*180/Math.PI,distance:points.length>1?Math.hypot(a.x-b.x,a.y-b.y):0}}
touchCanvas.addEventListener('pointerdown',e=>{if($('#editPreview').classList.contains('show-result')||activeImage().empty)return;e.preventDefault();if(!touchPoints.size)rememberCrop();touchPoints.set(e.pointerId,{x:e.clientX,y:e.clientY});touchCanvas.setPointerCapture(e.pointerId);gestureBaseline();touchCanvas.classList.add('dragging')});
touchCanvas.addEventListener('pointermove',e=>{if(!touchPoints.has(e.pointerId)||!touchGesture)return;e.preventDefault();touchPoints.set(e.pointerId,{x:e.clientX,y:e.clientY});const points=[...touchPoints.values()],a=points[0],b=points[1]||a,c=activeImage(),g=touchGesture;let zoom=g.zoom;if(points.length>1&&g.distance)zoom=Math.max(100,Math.min(300,g.zoom*Math.hypot(a.x-b.x,a.y-b.y)/g.distance));c.zoom=zoom;if(points.length>1&&g.distance){const angle=Math.atan2(b.y-a.y,b.x-a.x)*180/Math.PI;c.rotation=normalizeAngle(g.rotation+normalizeAngle(angle-g.angle))}const crop=$('#touchCrop'),w=crop.clientWidth,h=crop.clientHeight;const iw=c.width||736,ih=c.height||736;const cover=previewMode==='poster'?Math.min(w/iw,h/ih):Math.max(w/iw,h/ih);const extraX=Math.max(40,iw*cover*zoom/100-w),extraY=Math.max(40,ih*cover*zoom/100-h);const limitX=Math.max(0,(iw*cover*zoom/100-w)/2/w*100),limitY=Math.max(0,(ih*cover*zoom/100-h)/2/h*100);c.panX=Math.max(-limitX,Math.min(limitX,g.panX+((a.x+b.x)/2-g.cx)/w*100));c.panY=Math.max(-limitY,Math.min(limitY,g.panY+((a.y+b.y)/2-g.cy)/h*100));paintTouchArt($('#touchArt'),c,w,h);$('#touchZoomValue').textContent=Math.round(c.zoom)+'%';$('#touchAngleValue').textContent=Math.round(c.rotation||0)+'°';});
function finishPointer(e){if(!touchPoints.has(e.pointerId))return;touchPoints.delete(e.pointerId);if(touchCanvas.hasPointerCapture(e.pointerId))touchCanvas.releasePointerCapture(e.pointerId);gestureBaseline();if(!touchPoints.size){touchCanvas.classList.remove('dragging');render()}}
touchCanvas.addEventListener('pointerup',finishPointer);touchCanvas.addEventListener('pointercancel',finishPointer);
$('#touchDone').onclick=()=>toggleEditor(false);$('#touchReplace').onclick=()=>$('#upload').click();$('#touchSettings').onclick=()=>{document.body.classList.add('touch-details');$('#name').focus()};$('#touchReset').onclick=()=>{rememberCrop();Object.assign(activeImage(),{position:50,positionY:50,zoom:100,panX:0,panY:0,rotation:0});render()};$('#touchUndo').onclick=()=>{const last=touchHistory.pop();if(!last)return;selected=last.slot;previewMode=last.mode;syncSceneButtons();Object.assign(activeImage(),{position:last.position,positionY:last.positionY,zoom:last.zoom,panX:last.panX||0,panY:last.panY||0,rotation:last.rotation||0});render()};
function touchZoomBy(amount){rememberCrop();activeImage().zoom=Math.max(100,Math.min(300,activeImage().zoom+amount));render()}
$('#touchZoomOut').onclick=()=>touchZoomBy(-10);$('#touchZoomIn').onclick=()=>touchZoomBy(10);$('#touchResult').onclick=()=>{const show=$('#editPreview').classList.toggle('show-result');$('#touchResult').setAttribute('aria-pressed',show);queueEditPreview()};touchCanvas.addEventListener('keydown',e=>{const keys={ArrowLeft:[3,0],ArrowRight:[-3,0],ArrowUp:[0,3],ArrowDown:[0,-3]};if(keys[e.key]){e.preventDefault();rememberCrop();const c=activeImage();c.position=Math.max(0,Math.min(100,c.position+keys[e.key][0]));c.positionY=Math.max(0,Math.min(100,(c.positionY??50)+keys[e.key][1]));render()}else if(e.key==='+'||e.key==='=')touchZoomBy(10);else if(e.key==='-')touchZoomBy(-10)});

function normalizeAngle(degrees){return ((degrees+180)%360+360)%360-180}
function syncSceneButtons(){document.querySelectorAll('[data-preview]').forEach(x=>x.setAttribute('aria-pressed',x.dataset.preview===previewMode||(x.dataset.preview==='poster'&&isDetail(previewMode))))}
function rotateImage(by){rememberCrop();activeImage().rotation=normalizeAngle((activeImage().rotation||0)+by);render()}
$('#rotateLeft').onclick=()=>rotateImage(-5);$('#rotateRight').onclick=()=>rotateImage(5);$('#rotateQuarter').onclick=()=>rotateImage(90);$('#rotateReset').onclick=()=>{rememberCrop();activeImage().rotation=0;render()};


document.querySelectorAll('[data-part]').forEach(b=>b.onclick=()=>{previewMode=b.dataset.part;syncSceneButtons();$('#editPreview').classList.remove('show-result');$('#touchResult').setAttribute('aria-pressed','false');render()});
$('#detailTitle').oninput=$('#detailNote').oninput=()=>{preparePoster(null,selected);queueEditPreview()};

$('#designOnly').onclick=()=>{const on=$('#posterStage').classList.toggle('design-only');$('#designOnly').setAttribute('aria-pressed',on);$('#designOnly').textContent=on?'이미지 표시':'디자인만 보기'};
